import{M as e,h as t,p as n,t as r}from"./plugin-vue_export-helper-Dy_UwxR5.js";var i=JSON.parse(`{"path":"/forge/box/2.%E9%94%BB%E9%80%A0%E9%94%A4%E6%94%B9%E9%80%A0.html","title":"锻造锤改造 | 原版文档","lang":"zh-CN","frontmatter":{"title":"锻造锤改造","createTime":"2026/3/30","icon":"/icon/tetra.svg"},"git":{},"filePathRelative":"forge/box/2.锻造锤改造.md","headers":[]}`),a={name:`2.锻造锤改造.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<p class="read-more">本包自1.1版本开始加入了锻造锤模块化改造玩法以取代原本的锻造师等级玩法且锻造锤<strong>不再需要放置热电池提供动力</strong>，一切对锻造锤的改造都将在加工台进行。</p><div class="hint-container important"><p class="hint-container-title">重要</p><p>锻造锤未经改造无法使用！</p></div><h2 id="锻造锤词条" tabindex="-1"><a class="header-anchor" href="#锻造锤词条"><span>锻造锤词条</span></a></h2><p>模块化锻造锤拥有 <strong>[不稳]</strong> <strong>[稳定]</strong> <strong>[锻造锤]</strong>三个词条。</p><ol><li><strong>[不稳]</strong>：锻造锤在改造时每级故障率提升1%。</li><li><strong>[稳定]</strong>锻造锤在改造时每级故障率降低1%。</li></ol><div class="hint-container note"><p class="hint-container-title">注</p><p>锻造锤初始拥有30%的故障概率，故障后锤头会掉落下来无法复位，需要4级及以上锤头右击锤头方块复位</p></div><ol start="3"><li><strong>[锻造锤]</strong>：锻造锤生效时提每级供1锤头等级。</li></ol><hr><p><img src="/assets/image10-BHC0z4WY.webp" alt="锻造锤" width="400" loading="lazy"></p><p>如图所示模块化锻造锤，该锻造锤有<strong>5锤头等级</strong>和<strong>30+22-2=50%</strong>故障率</p><div class="hint-container note"><p class="hint-container-title">注</p><p>该处的<strong>30</strong>为上述<strong>初始30%故障率</strong>，<mark class="danger">并非图中展示的火焰伤害数值</mark>。</p></div><h2 id="锻造锤模块" tabindex="-1"><a class="header-anchor" href="#锻造锤模块"><span>锻造锤模块</span></a></h2><p>锻造锤改造模块包括<strong>外壳</strong>、<strong>锤头</strong>、<strong>强化槽</strong>。</p><h3 id="外壳" tabindex="-1"><a class="header-anchor" href="#外壳"><span>外壳</span></a></h3><p>提供 <strong>[不稳]</strong> 和<mark>总完整度</mark>。依据材料硬度调整 <strong>[不稳]</strong> 等级，<mark>硬度</mark> 越 <mark class="danger">低</mark> <strong>[不稳]</strong> 等级越高。</p><h3 id="锤头" tabindex="-1"><a class="header-anchor" href="#锤头"><span>锤头</span></a></h3><p>提供 <strong>[稳定]</strong>并提供5级基础锤等级，依据材料韧性调整 <strong>[稳定]</strong> 等级，<mark>韧性</mark>越 <mark class="tip">高</mark> <strong>[稳定]</strong> 等级越高。</p><h3 id="强化槽" tabindex="-1"><a class="header-anchor" href="#强化槽"><span>强化槽</span></a></h3><p>每个锻造锤有<strong>两个强化槽</strong>，本体固定材料为<mark>锻造钢锭</mark>，提供各种强化选项。</p><h2 id="锻造锤强化" tabindex="-1"><a class="header-anchor" href="#锻造锤强化"><span>锻造锤强化</span></a></h2><h3 id="锤头强化" tabindex="-1"><a class="header-anchor" href="#锤头强化"><span>锤头强化</span></a></h3><p><img src="/assets/image11-C_BaqzLg.webp" alt="强化" width="400" loading="lazy"></p><ul><li><p><strong>元素锻锤</strong>：第一个栏位放<code>锻造模板(魔麟)</code>,根据第二个材料来获取加成。</p><ul><li><table><thead><tr><th style="text-align:center;">风</th><th style="text-align:center;">火</th><th style="text-align:center;">毒</th><th style="text-align:center;">雷</th></tr></thead><tbody><tr><td style="text-align:center;">漂浮核心</td><td style="text-align:center;">必火恶怪粘胶</td><td style="text-align:center;">裂变核心</td><td style="text-align:center;">闪电蠕虫甲壳</td></tr></tbody></table></li></ul></li></ul><div class="hint-container note"><p class="hint-container-title">注</p><p>每个锻造锤只能同时容纳一种元素锻锤的强化。</p></div><ul><li><p><strong>精密锻锤</strong>：改造部件时保留原词条属性，<mark>使用16个<code>高级处理器</code></mark>。</p></li><li><p><strong>原初气息</strong>：改造时，消耗玩家消耗<mark>400点营养值</mark>，让<code>活体剑刃</code>沾染<mark>原初气息</mark>，活体剑刃生命转伤害的倍率增加40%。</p><ul><li>使用16个原初核心、1个蕾莓、3个下界之星。</li></ul></li></ul><h3 id="强化槽强化" tabindex="-1"><a class="header-anchor" href="#强化槽强化"><span>强化槽强化</span></a></h3><p>两个相同强化可叠加，但每一个都会消耗完整度。</p><p><img src="/assets/image12-B6huVXuU.webp" alt="强化槽" width="400" loading="lazy"></p><ul><li><p><strong>燃烧室</strong>：增加1额外锤等级</p><ul><li>使用1个燃烧室，不消耗完整度。</li></ul></li><li><p><strong>易加工</strong>：增加1级易加工等级</p><ul><li>使用1个无瑕青金石，消耗1完整度。</li></ul></li><li><p><strong>润滑剂发射器</strong>：减少15%的锻造锤基础故障概率</p><ul><li>使用1个润滑剂发射器，消耗1完整度。</li></ul></li><li><p><strong>莫厄能源</strong>：再增加1额外锤等级</p><ul><li>使用1个莫厄能源体，不消耗完整度。</li></ul></li><li><p><strong>平面稳定器</strong>：增加高质量等级 <mark>一个增加2级，两个增加3级</mark></p><ul><li>使用1个平面稳定器，消耗1完整度。</li></ul></li><li><p><strong>震荡室</strong>：增加1级稳固词条</p><ul><li>使用1个震击室，消耗1完整度。</li></ul></li></ul><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>版本已知性能最好的锻造锤可以同时容纳以上所有强化，请玩家自行探索。</p></div>`,30)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};